    const auto model = std::find_if(files.begin(), files.end(), [&](const auto& file) { return !has_extension(file, ".zip"); });
    if (model == files.end())
        return false;

    BOOST_LOG_TRIVIAL(info) << "JusPrin opens " << files.size() << " file(s) as a new project: " << model->string();
