void OrcaHomeBackend::open_dropped_files(const std::vector<DroppedFile>& files)
{
    Plater* plater = wxGetApp().plater();
    if (plater == nullptr)
        return;
    // The page gives a dropped file's bytes but not its path. Each is kept
    // under a folder named by its content, so the same file dropped again
    // has the same path, and a .3mf among them can be recognized as opened
    // before. A file opened from its own folder has a different path.
    const boost::filesystem::path root = boost::filesystem::temp_directory_path() / "JusPrin-dropped";
    wxArrayString paths;
    for (const DroppedFile& file : files) {
        const boost::filesystem::path name = boost::filesystem::path(from_u8(file.name).ToStdWstring()).filename();
        if (name.empty() || name == "." || name == "..")
            continue;
        try {
            const boost::filesystem::path incoming = root / boost::filesystem::unique_path() / name;
            boost::filesystem::create_directories(incoming.parent_path());
            boost::nowide::ofstream(incoming.string(), std::ios::binary).write(file.bytes.data(), std::streamsize(file.bytes.size()));
            std::string digest;
            bbl_calc_md5(incoming.string(), digest);
            const boost::filesystem::path kept = root / digest / name;
            if (digest.empty() || boost::filesystem::exists(kept)) {
                if (!digest.empty())
                    boost::filesystem::remove_all(incoming.parent_path());
            } else {
                boost::filesystem::create_directories(kept.parent_path());
                boost::filesystem::rename(incoming, kept);
                boost::filesystem::remove_all(incoming.parent_path());
            }
            paths.Add(from_path(digest.empty() ? incoming : kept));
        } catch (const std::exception& error) {
            BOOST_LOG_TRIVIAL(error) << "Home could not keep a dropped file " << file.name << ": " << error.what();
        }
    }
    if (!paths.empty())
        plater->load_files(paths);
}

